import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const mobileRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const markerPath = join(mobileRoot, 'build/verification.txt');

mkdirSync(dirname(markerPath), { recursive: true });
writeFileSync(
  markerPath,
  [
    'TaskNebula mobile build verification passed.',
    'This marker is generated by pnpm --filter @tasknebula/mobile build.',
    '',
  ].join('\n'),
);

console.log(`Mobile build marker written: ${markerPath}`);
